mapper.select:
SELECT
t1.*
FROM
project_reform t1
where
    t1.tenant = #{tenant}

        and t1.update_time >= #{period.begin}


        and t1.update_time <= #{period.end}

SELECT TRUNCATE ( temp.`processing_time` / temp.`total_count`, 0 ) AS `avg_process_seconds` FROM ( SELECT COUNT( t1.id ) total_count, COALESCE ( SUM( TIMESTAMPDIFF( SECOND, t1.create_time, t1.pass_time )), 0 ) AS `processing_time` FROM project_reform t1 WHERE t1.approve_result = 'PASS'
and t1.update_time >= #{period.begin}
and t1.update_time <= #{period.end}
) temp
